import csv
import io

def parse_csv(raw_csv: str):
    csv.field_size_limit(2147483647)
    records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))

    if not records:
        return {"columns": [], "rows": []}

    header = records[0]
    if header:
        header[0] = header[0].lstrip("\ufeff")

    width = max(len(row) for row in records)
    reserved = {name for name in header if name}
    used = set()
    columns = []

    for i in range(width):
        name = header[i] if i < len(header) else ""
        if not name or name in used:
            base = name if name else f"column_{i + 1}"
            candidate = base
            suffix = 2
            while candidate in used or candidate in reserved:
                candidate = f"{base}_{suffix}"
                suffix += 1
            name = candidate
        columns.append(name)
        used.add(name)

    rows = [row + [""] * (width - len(row)) for row in records[1:]]
    return {"columns": columns, "rows": rows}
